import { Component } from '@angular/core';
import { Router } from '@angular/router';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { AuthService } from '../../services/auth.service';

@Component({
  selector: 'app-login',
  templateUrl: './login.component.html',
  styleUrls: ['./login.component.css']
})
export class LoginComponent {
  public imagePath = 'assets/administration.jpg';
  public loginForm: FormGroup;
  public alertMessage: string = '';
  public alertType: 'success' | 'error' = 'error';
  public showModal: boolean = false;

  constructor(
    private router: Router,
    private fb: FormBuilder,
    private authService: AuthService
  ) {
    this.loginForm = this.fb.group({
      email: ['', [Validators.required, Validators.email]],
      lozinka: ['', Validators.required]
    });
  }

  public goToRegister(): void {
    this.router.navigate(['/register']);
  }

  private showAlert(message: string, type: 'success' | 'error' = 'error') {
    this.alertMessage = message;
    this.alertType = type;
    this.showModal = true;
  }

  public handleModalClose() {
    this.showModal = false;
    if (this.alertType === 'success') {
      this.router.navigate(['/dashboard']); // ili neka početna stranica posle logina
    }
  }

  public onSubmit(): void {
    if (this.loginForm.valid) {
      const { email, lozinka } = this.loginForm.value;

      this.authService.login(email, lozinka).subscribe({
        next: (response: any) => {
          // Sačuvaj token u localStorage/sessionStorage
          localStorage.setItem('jwtToken', response.token);
          this.showAlert('Uspešna prijava!', 'success');
        },
        error: (err) => {
          this.showAlert(err.error || 'Neispravan email ili lozinka', 'error');
        }
      });

    } else {
      this.showAlert('Molimo popunite sva polja ispravno.', 'error');
    }
  }
}
<section class="vh-100">
  <div class="container py-5 h-100">
    <div class="row d-flex justify-content-center align-items-center h-100">
      <div class="col col-xl-10">
        <div class="card">
          <div class="row g-0">
            <div class="col-md-6 col-lg-5 d-none d-md-block">
              <img [src]="imagePath" alt="login form" class="img-fluid" />
            </div>
            <div class="col-md-6 col-lg-7 d-flex align-items-center">
              <div class="card-body p-4 p-lg-5">
                <h1 class="text-center fw-bold mb-4">Sign In</h1>

                <form [formGroup]="loginForm" (ngSubmit)="onSubmit()">
                  <div class="form-outline mb-4">
                    <label class="form-label" for="email">Email</label>
                    <input type="email" id="email" class="form-control form-control-lg" formControlName="email" placeholder="Enter your email" />
                  </div>

                  <div class="form-outline mb-4">
                    <label class="form-label" for="password">Password</label>
                    <input type="password" id="password" class="form-control form-control-lg" formControlName="lozinka" placeholder="Enter your password" />
                  </div>

                  <div class="pt-1 mb-4">
                    <button class="btn btn-dark btn-lg btn-block" type="submit">Login</button>
                  </div>

                  <p class="mb-5 pb-lg-2">
                    Don't have an account? <a (click)="goToRegister()" class="register-link">Register here</a>
                  </p>
                </form>

              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  </div>
</section>

<!-- Custom modal for login success/error -->
<app-custom-alert
  *ngIf="showModal"
  [message]="alertMessage"
  [type]="alertType"
  (closed)="handleModalClose()">
</app-custom-alert>
